	'messages:apihelp-query+managemessagegroups-param-changesetName' => 'en:Changeset name - Default / Unattended / MediaWiki etc.',
	'messages:apihelp-query+messagecollection-param-filter' => 'en:Message collection filters. Use <kbd>!</kbd> to negate condition. For example <kbd>!fuzzy</kbd> means list only all non-fuzzy messages. Filters are applied in the order given.
;fuzzy:Messages with fuzzy tag.
;optional:Messages which should be translated only if changes are necessary.
;ignored:Messages which are never translated.
;hastranslation:Messages which have a translation regardless if it is fuzzy or not.
;translated:Messages which have a translation which is not fuzzy.
;changed:Messages which have been translated or changed since last export.
;reviewer&#58;N:Messages where the user number <kbd>N</kbd> is among reviewers.
;last-translator&#58;N:Messages where the user number <kbd>N</kbd> is the last translator.',
	'messages:apihelp-query+messagecollection-param-prop' => 'en:Which properties to get:',
	'messages:apihelp-query+messagecollection-paramvalue-prop-translation' => 'en:Current translation (without $1 string if any, use the tags to check for outdated or broken translations).',
	'messages:apihelp-query+messagegroups-param-prop' => 'en:What translation-related information to get:',
	'messages:apihelp-query+messagegroups-paramvalue-prop-subscription' => 'en:Include whether the user is subscribed to the group.',
	'messages:apihelp-query+messagegroups-param-root' => 'en:When using the tree format, instead of starting from top level start from the given message group, which must be an aggregate message group. When using flat format only the specified group is returned.',
	'messages:apihelp-query+messagegroupsubscription-summary' => 'en:List message groups the current user is subscribed to.',
	'messages:apihelp-managemessagegroups-param-renameMessageKey' => 'en:Target message key being renamed',
	'messages:apihelp-managemessagegroups-param-messageKey' => 'en:Replacement message key',
	'messages:apihelp-managemessagegroups-param-changesetName' => 'en:Changeset name - Default / Unattended / MediaWiki etc.',
	'messages:apihelp-managegroupsynchronizationcache-param-title' => 'en:Message title being marked as resolved',
	'messages:apihelp-managegroupsynchronizationcache-param-group' => 'en:Group Id of the message being resolved. See <kbd>[[Special:ApiHelp/query+messagegroups|action=query&meta=messagegroups]]</kbd>.',
	'messages:apihelp-messagegroupsubscription-summary' => 'en:Message group subscription related operations',
	'messages:apihelp-messagegroupsubscription-param-groupId' => 'en:Message group ID for the group being subscribed to. See <kbd>[[Special:ApiHelp/query+messagegroups|action=query&meta=messagegroups]]</kbd>.',
	'messages:apihelp-messagegroupsubscription-param-operation' => 'en:The operation to be performed.',
	'messages:apihelp-markfortranslation-summary' => 'en:Mark a page for translation',
	'messages:apihelp-markfortranslation-param-title' => 'en:The title of the page to act on. Either <var>title</var> or <var>pageid</var> must be set.',
	'messages:apihelp-markfortranslation-param-pageid' => 'en:The page ID of the page to act on. Either <var>title</var> or <var>pageid</var> must be set.',
	'messages:apihelp-markfortranslation-param-revid' => 'en:Assert that the current version of the page has this revision ID before continuing. If the page has been updated, exit with an error.',
	'messages:apihelp-markfortranslation-param-translatetitle' => 'en:If <kbd>yes</kbd>, allow translation of the display title. If <kbd>no</kbd>, do not allow translation. If absent, allow translation unless the page previously disallowed translation, or if the page is a template.',
	'messages:apihelp-markfortranslation-param-prioritylanguages' => 'en:A list of priority language codes. If this is absent, any previously set value will be retained.',
	'messages:apihelp-markfortranslation-param-forcepriority' => 'en:This parameter is ignored unless the <var>prioritylanguages</var> parameter is present. If <kbd>true</kbd>, prevent translations to languages other than the priority languages.',
	'messages:apihelp-markfortranslation-param-priorityreason' => 'en:This parameter is ignored unless the <var>prioritylanguages</var> parameter is present. A string giving the reason for priority translation.',
	'messages:apihelp-markfortranslation-param-nofuzzyunits' => 'en:A list of translation unit IDs which should not be fuzzied. This will be merged with the default list, in which any units with only tvar changes will not be fuzzied.',
	'messages:apihelp-markfortranslation-param-fuzzyunits' => 'en:A list of translation unit IDs which should be fuzzied. This is only useful to override the default and allows fuzzying even units with only tvar changes.',
	'messages:apihelp-markfortranslation-param-forcelatestsyntaxversion' => 'en:If <kbd>false</kbd>, do not use latest syntax version for this page. If absent, latest syntax version is used.',
	'messages:apihelp-markfortranslation-param-transclusion' => 'en:If <kbd>yes</kbd> or absent, enable translation aware transclusion for this page. If <kbd>no</kbd>, disable transclusion.',
	'messages:apierror-translate-changeset-modified' => 'en:The changeset has been modified by another user or process. Your changes cannot be saved as it might override their changes. Please refresh the page to see the latest changes.',
